import{basename}from"node:path";import readline from"node:readline/promises";import{ChatHistory,VLMPipeline}from"openvino-genai-node";import{hideBin}from"yargs/helpers";import yargs from"yargs/yargs";import{readImages}from"../image_utils.js";function streamer(e){process.stdout.write(e)}async function main(){const e=yargs(hideBin(process.argv)).scriptName(basename(process.argv[1])).command("$0 model_dir image_path [device] [prompt_lookup]","Run image-to-text chat",(e=>e.positional("model_dir",{type:"string",describe:"Path to the VLM model directory",demandOption:!0}).positional("image_path",{type:"string",describe:"Path to an image file or a directory with images",demandOption:!0}).positional("device",{type:"string",describe:"Device name (e.g., CPU, GPU)",default:"CPU"}).positional("prompt_lookup",{type:"boolean",describe:"Enable prompt lookup decoding (true/false)",default:!1}))).strict().help().parse(),{model_dir:t,image_path:o,device:r,prompt_lookup:a}=e,i=await readImages(o),s={prompt_lookup:a};"GPU"===r&&(s.CACHE_DIR="vlm_cache");const n=await VLMPipeline(t,r,s),p={max_new_tokens:100};a&&(p.num_assistant_tokens=5,p.max_ngram_size=3);const m=readline.createInterface({input:process.stdin,output:process.stdout});async function c(e){try{return await m.question(e)}catch{return null}}try{const e=new ChatHistory;let t=await c("question:\n");if(!t)return;e.push({role:"user",content:t});let o=await n.generate(e,{generationConfig:p,streamer:streamer,images:i});for(process.stdout.write("\n"),e.push({role:"assistant",content:o.texts[0]});t=await c("----------\nquestion:\n"),t;)e.push({role:"user",content:t}),o=await n.generate(e,{generationConfig:p,streamer:streamer}),process.stdout.write("\n"),e.push({role:"assistant",content:o.texts[0]})}finally{m.close()}}main().catch((e=>{console.error(e),process.exit(1)}));